function section(href: string) { try { const document = host.value?.ownerDocument; if (!document) return null; const url = new URL(href, document.location.href); if (url.origin !== document.location.origin || url.pathname !== document.location.pathname || url.search !== document.location.search || !url.hash) return null; return document.getElementById(decodeURIComponent(url.hash.slice(1))); } catch { return null; } }
function measure() { if (!target) return; const metrics = scrollMetrics(target), extent = 'window' in target ? host.value!.ownerDocument.documentElement.scrollHeight : target.scrollHeight; const valid = links.value.map(item => ({ href: item.href, element: section(item.href) })).filter(item => item.element); const passed = valid.filter(item => item.element!.getBoundingClientRect().top - metrics.origin <= bounded(props.offset,0,10000,12) + 2); const atEnd = extent > metrics.height + 2 && metrics.top + metrics.height >= extent-2; const next = (atEnd ? valid.at(-1)?.href : passed.at(-1)?.href) ?? valid[0]?.href ?? ''; if (next !== active.value) { active.value = next; emit('change',next); } }
function schedule() { const browser = browserOf(host.value); if (!browser || frame) return; frame = browser.requestAnimationFrame(() => { frame = 0; measure(); }); }
