<template><nav ref="host" class="ui-anchor" :aria-label="label"><a v-for="(item,index) in links" :key="`${item.href}-${index}`" :href="item.href" :style="{ paddingInlineStart: `${12 + item.depth*16}px` }" :aria-current="active === item.href ? 'location' : undefined" @click="navigate(item,$event)">{{ item.label }}</a><p v-if="!links.length">暂无目录。</p></nav></template>
